package solution
import("strconv";"strings")
func ShardRouting(s string)(string,bool){p:=strings.Split(s,";");if len(p)!=2||p[1]==""{return "",false};n,e:=strconv.Atoi(p[0]);if e!=nil||n<1||n>1024||strconv.Itoa(n)!=p[0]{return "",false};o:=[]string{};for _,k:=range strings.Split(p[1],","){if k==""{return "",false};sum:=0;for _,c:=range []byte(k){if c<32||c>126||c==','||c==';'{return "",false};sum+=int(c)};o=append(o,k+"="+strconv.Itoa(sum%n))};return strings.Join(o,","),true}
